  "ui.archive.cacheHelp": {"ko": "저장된 DB를 먼저 표시합니다. 파일 변경분은 필요할 때 다시 읽으세요.", "en": "Display the saved database first. Read the directory again to update changed files.", "ja": "保存済みDBを先に表示します。ファイルの変更を反映するときは再読み込みしてください。", "es": "Muestra primero la base de datos guardada. Vuelve a leer la carpeta para actualizar los archivos cambiados.", "fr": "Affiche d’abord la base de données enregistrée. Relisez le dossier pour actualiser les fichiers modifiés."},
  "ui.archive.emptyTitle": {"ko": "Archive에 보관된 게임이 없습니다.", "en": "No games are stored in Archive.", "ja": "Archiveにゲームがありません。", "es": "No hay juegos guardados en Archive.", "fr": "Aucun jeu stocké dans Archive."},
  "ui.archive.emptyHelp": {"ko": "Collection에서 게임을 복사한 뒤 여기에 붙여넣으세요.", "en": "Copy games from a Collection, then paste them here.", "ja": "Collectionでゲームをコピーし、ここに貼り付けてください。", "es": "Copia juegos de una Collection y pégalos aquí.", "fr": "Copiez des jeux d’une Collection, puis collez-les ici."},
