  "ui.scraper.mediaHelp": {"ko": "스크랩 후보에서 내려받을 종류를 고릅니다.", "en": "Choose which media types to download from the selected candidate.", "ja": "選択した候補から取得するメディアの種類を選びます。", "es": "Elige los tipos de medios que se descargarán del candidato seleccionado.", "fr": "Choisissez les types de médias à télécharger pour le candidat sélectionné."},
  "ui.scraper.dat": {"ko": "식별 데이터", "en": "Identification data", "ja": "識別データ", "es": "Datos de identificación", "fr": "Données d’identification"},
  "ui.scraper.datAdd": {"ko": "DAT 추가…", "en": "Add DAT…", "ja": "DATを追加…", "es": "Añadir DAT…", "fr": "Ajouter un DAT…"},
  "ui.scraper.datEmpty": {"ko": "가져온 DAT 없음", "en": "No imported DAT files", "ja": "取り込んだDATはありません", "es": "No hay archivos DAT importados", "fr": "Aucun fichier DAT importé"},
  "ui.scraper.datLoading": {"ko": "가져온 DAT를 확인하는 중…", "en": "Checking imported DAT files…", "ja": "取り込んだDATを確認中…", "es": "Comprobando archivos DAT importados…", "fr": "Vérification des fichiers DAT importés…"},
  "ui.scraper.datHelp": {"ko": "보유한 Logiqx DAT 또는 MAME listxml을 가져오면 ROM 코드명과 CRC를 정식 제목 검색에 활용합니다. 결과는 직접 확인해야 합니다.", "en": "Import a Logiqx DAT or MAME listxml to use ROM short names and CRCs for title searches. Review the results before applying.", "ja": "Logiqx DATまたはMAME listxmlを取り込むと、ROMコード名とCRCを正式タイトルの検索に利用できます。適用前に結果を確認してください。", "es": "Importa un DAT Logiqx o listxml de MAME para usar los nombres cortos y CRC de las ROMs al buscar títulos. Revisa los resultados antes de aplicarlos.", "fr": "Importez un DAT Logiqx ou un listxml MAME pour utiliser les noms courts et CRC des ROMs dans la recherche de titres. Vérifiez les résultats avant de les appliquer."},
  "ui.scraper.connectionUnknown": {"ko": "연결 상태를 확인하지 않았습니다.", "en": "Connection has not been tested.", "ja": "接続は未確認です。", "es": "La conexión no se ha probado.", "fr": "La connexion n’a pas été testée."},
  "ui.scraper.connect": {"ko": "연결 설정…", "en": "Connection settings…", "ja": "接続設定…", "es": "Configurar conexión…", "fr": "Configurer la connexion…"},
  "ui.scraper.test": {"ko": "연결 테스트", "en": "Test connection", "ja": "接続テスト", "es": "Probar conexión", "fr": "Tester la connexion"},
  "ui.core.doubleClick": {"ko": "게임 행을 더블클릭하거나 Detail의 ▶ 버튼으로 실행합니다.", "en": "Double-click a game row or use the ▶ button in the detail panel.", "ja": "ゲーム行をダブルクリックするか、詳細パネルの▶で起動します。", "es": "Haz doble clic en un juego o usa ▶ en el panel de detalles.", "fr": "Double-cliquez sur un jeu ou utilisez ▶ dans le panneau de détails."},
  "ui.core.pathHelp": {"ko": "Core는 이 폴더 기준 파일명으로 기억합니다 - RetroArch를 옮겨도 폴더만 다시 지정하면 됩니다.", "en": "Core filenames are stored relative to this folder. If you move RetroArch, select its new core folder.", "ja": "Coreのファイル名はこのフォルダーからの相対パスで保存します。RetroArchを移動したらCoreフォルダーを指定し直してください。", "es": "Los nombres de los cores se guardan respecto a esta carpeta. Si mueves RetroArch, selecciona la nueva carpeta de cores.", "fr": "Les noms des cores sont enregistrés relativement à ce dossier. Si vous déplacez RetroArch, sélectionnez le nouveau dossier de cores."},
  "ui.core.chooseFolder": {"ko": "Core 폴더를 지정하면 설치된 Core 목록에서 고를 수 있습니다.", "en": "Select a core folder to choose from installed cores.", "ja": "Coreフォルダーを指定して、インストール済みCoreから選択します。", "es": "Selecciona una carpeta de cores para elegir entre los instalados.", "fr": "Sélectionnez un dossier de cores pour choisir parmi ceux installés."},
  "ui.core.unverified": {"ko": "이 System의 Core/BIOS 조합은 아직 검증되지 않았습니다. 선택한 Core로 실행할 수 있습니다.", "en": "This system's core/BIOS combination has not been verified. You can still launch with the selected core.", "ja": "このシステムのCore/BIOSの組み合わせは未検証です。選択したCoreで起動できます。", "es": "La combinación de core y BIOS no se ha verificado. Puedes ejecutar el core seleccionado.", "fr": "Cette combinaison core/BIOS n’a pas été vérifiée. Vous pouvez lancer le core sélectionné."},
  "ui.backup.about": {"ko": "진단과 화면 설정을 관리합니다.", "en": "Manage diagnostics and display settings.", "ja": "診断と画面設定を管理します。", "es": "Gestiona el diagnóstico y la configuración de pantalla.", "fr": "Gérez le diagnostic et les paramètres d’affichage."},
  "ui.backup.auto": {"ko": "백업 자동 정리", "en": "Automatic backup cleanup", "ja": "バックアップを自動整理", "es": "Limpiar copias de seguridad automáticamente", "fr": "Nettoyer automatiquement les sauvegardes"},
  "ui.backup.autoHelp": {"ko": "작업 완료 후 오래된 백업부터 정리합니다. 최신 실행 취소·복구 기록은 보존합니다.", "en": "Remove older backups after an operation completes. Keep the latest undo and recovery records.", "ja": "作業完了後に古いバックアップから整理します。最新の元に戻す記録と復旧記録は保持します。", "es": "Limpia las copias más antiguas tras completar una operación. Conserva los registros recientes de deshacer y recuperación.", "fr": "Nettoie les sauvegardes les plus anciennes après une opération. Conserve les derniers historiques d’annulation et de récupération."},
  "ui.backup.count": {"ko": "보관할 작업 수", "en": "Operations to retain", "ja": "保持する操作数", "es": "Operaciones que conservar", "fr": "Opérations à conserver"},
  "ui.backup.countHelp": {"ko": "Collection / Archive별 한도. 0은 제한 없음입니다.", "en": "Limit per Collection or Archive. Zero means unlimited.", "ja": "Collection / Archiveごとの上限です。0は無制限です。", "es": "Límite por Collection / Archive. 0 significa sin límite.", "fr": "Limite par Collection / Archive. 0 signifie aucune limite."},
  "ui.backup.size": {"ko": "보관 용량 (GB)", "en": "Backup size (GB)", "ja": "保持容量（GB）", "es": "Capacidad de conservación (GB)", "fr": "Capacité de conservation (Go)"},
  "ui.backup.sizeHelp": {"ko": "0은 제한 없음. 보호된 백업 때문에 한도를 초과할 수 있습니다.", "en": "Zero means unlimited. Protected backups may exceed the limit.", "ja": "0は無制限です。保護されたバックアップにより上限を超える場合があります。", "es": "0 significa sin límite. Las copias protegidas pueden superar el límite.", "fr": "0 signifie aucune limite. Les sauvegardes protégées peuvent dépasser la limite."},
  "ui.backup.recovery": {"ko": "파일 작업 복구", "en": "Recover file operations", "ja": "ファイル操作の復旧", "es": "Recuperación de operaciones de archivos", "fr": "Récupération des opérations de fichiers"},
  "ui.backup.recoveryHelp": {"ko": "복구 실패를 다시 시도하거나 백업을 보존한 채 기록을 닫습니다.", "en": "Retry a failed recovery or close its record while retaining the backup.", "ja": "復旧失敗を再試行するか、バックアップを保持して記録を閉じます。", "es": "Reintenta la recuperación o cierra el registro conservando la copia de seguridad.", "fr": "Réessayez la récupération ou fermez l’historique en conservant la sauvegarde."},
  "ui.backup.open": {"ko": "복구 기록 열기", "en": "Open recovery records", "ja": "復旧記録を開く", "es": "Abrir registros de recuperación", "fr": "Ouvrir les historiques de récupération"},
