// English legacy labels are UI, not stable IDs. Keep them localizable while
// callers migrate. Uppercase labels share the same meaning as title case.
for (const [source, key] of Object.entries({
  "INTERNAL":"ui.nav.internal", "EXTERNAL":"ui.nav.external", "EXTERNAL SD":"ui.nav.externalSD",
  "TITLE":"ui.list.title", "DESCRIPTION":"ui.list.description", "GENRE":"ui.list.genre",
  "REGION":"ui.list.region", "RATING":"ui.list.rating", "DEVELOPER":"ui.detail.developer",
  "PUBLISHER":"ui.detail.publisher", "RELEASE":"ui.detail.release", "PLAYERS":"ui.detail.players",
  "Game 삭제":"ui.menu.delete", "게임 정보 스크랩…":"ui.menu.scrape",
  "메타데이터 가져오기":"ui.menu.import"
})) {
  const forms = window.RMSI18n.getMessages()[key];
  window.RMSI18n.addTable({[source]:forms});
}

// Legacy provider strings during the move to structured evidence IDs.
// Match only known UI prefixes; game titles and descriptions stay raw.
window.RMSI18n.addPatterns([
  {re:/^"(.*)" 검색$/, forms:{en:'Searching "$1"',ja:'「$1」を検索中',es:'Buscando "$1"',fr:'Recherche de « $1 »'}},
  {re:/^DAT 읽는 중 · ([\d,]+)개 게임$/, forms:{en:'Reading DAT · $1 games',ja:'DAT読み込み中 · $1件',es:'Leyendo DAT · $1 juegos',fr:'Lecture du DAT · $1 jeux'}},
  {re:/^검색어 "(.*)"$/, forms:{en:'Search name "$1"',ja:'検索名「$1」',es:'Nombre de búsqueda "$1"',fr:'Nom recherché « $1 »'}},
  {re:/^제목 유사도 ([\d.]+%) · 직접 확인 필요$/, forms:{en:'Title similarity $1 · review required',ja:'タイトル類似度 $1 · 確認が必要',es:'Similitud del título $1 · requiere revisión',fr:'Similarité du titre $1 · à vérifier'}},
  {re:/^제목 유사도 ([\d.]+%)$/, forms:{en:'Title similarity $1',ja:'タイトル類似度 $1',es:'Similitud del título $1',fr:'Similarité du titre $1'}},
]);
